INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (1, 'Disclosure Day', 'movie', '2026', 'Science Fiction', 'TV-14', 6.7, 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.', '/assets/posters/movie_1275779.jpg', '/assets/backdrops/movie_1275779.jpg', '/assets/video/clip_27152549.mp4', 7810, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (2, 'The Odyssey', 'movie', '2026', 'Adventure', 'TV-14', 7.9, 'Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.', '/assets/posters/movie_1368337.jpg', '/assets/backdrops/movie_1368337.jpg', '/assets/video/clip_27152555.mp4', 5782, 5, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (3, 'Backrooms', 'movie', '2026', 'Horror', 'TV-14', 7.1, 'A strange doorway appears in the basement of a furniture showroom.', '/assets/posters/movie_1083381.jpg', '/assets/backdrops/movie_1083381.jpg', '/assets/video/clip_30070091.mp4', 6607, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (4, 'Scary Movie', 'movie', '2026', 'Comedy', 'TV-14', 6.3, 'Twenty-six years after outrunning a suspiciously familiar masked killer, the Core Four are back in the killer''s crosshairs and no horror movie IP is safe.', '/assets/posters/movie_1273221.jpg', '/assets/backdrops/movie_1273221.jpg', '/assets/video/clip_30997958.mp4', 6436, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (5, 'The Mandalorian and Grogu', 'movie', '2026', 'Fantasy', 'TV-14', 6.7, 'The evil Empire has fallen, and Imperial warlords remain scattered throughout the galaxy. As the fledgling New Republic works to protect everything the Rebellion fought for, they have enlisted the help of legendary Mandalorian bounty hunter Din Djarin and his young apprentice Grogu.', '/assets/posters/movie_1228710.jpg', '/assets/backdrops/movie_1228710.jpg', '/assets/video/clip_35079542.mp4', 8130, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (6, 'Obsession', 'movie', '2026', 'Horror', 'TV-14', 8.2, 'After breaking the mysterious "One Wish Willow" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.', '/assets/posters/movie_1339713.jpg', '/assets/backdrops/movie_1339713.jpg', '/assets/video/clip_18972999.mp4', 7933, 3, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (7, 'Spider-Man: Brand New Day', 'movie', '2026', 'Science Fiction', 'TV-14', 0.0, 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', '/assets/posters/movie_969681.jpg', '/assets/backdrops/movie_969681.jpg', '/assets/video/clip_27152549.mp4', 8644, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (8, 'Descendants: Wicked Wonderland', 'movie', '2026', 'Fantasy', 'TV-14', 7.8, 'Now that the Queen of Hearts is nice and Cinderella is safe, things seem perfect for Red and Chloe… But little do they know that changing the past created a new villain — Maddox Hatter. When Maddox captures the Queen of Hearts, Red and Chloe must work alongside Red’s new sister Pink, Luisa Madrigal’s son Luis, and Maddox’s son Max to save her and Wonderland.', '/assets/posters/movie_1318621.jpg', '/assets/backdrops/movie_1318621.jpg', '/assets/video/clip_27152555.mp4', 5986, 6, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (9, 'The Death of Robin Hood', 'movie', '2026', 'Adventure', 'TV-14', 6.7, 'Grappling with his past after a life of crime and murder, Robin Hood finds himself gravely injured after a battle he thought would be his last. In the hands of a mysterious woman, he is offered a chance at salvation.', '/assets/posters/movie_1284465.jpg', '/assets/backdrops/movie_1284465.jpg', '/assets/video/clip_30070091.mp4', 7092, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (10, 'Moana', 'movie', '2026', 'Family', 'TV-14', 5.8, 'Teenage Moana answers the Ocean''s call and, for the first time, voyages beyond the reef of her island of Motunui with infamous demigod Maui on an unforgettable journey to restore prosperity to her people.', '/assets/posters/movie_1108427.jpg', '/assets/backdrops/movie_1108427.jpg', '/assets/video/clip_30997958.mp4', 5798, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (11, 'Avengers: Doomsday', 'movie', '2026', 'Science Fiction', 'TV-14', 0.0, 'Beloved heroes from three distinct universes are set on a deadly collision course and face an existential threat unlike anything they''ve ever encountered.', '/assets/posters/movie_1003596.jpg', '/assets/backdrops/movie_1003596.jpg', '/assets/video/clip_35079542.mp4', 6421, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (12, 'The Furious', 'movie', '2026', 'Action', 'TV-14', 7.4, 'After a criminal network kidnaps Wang Wei''s daughter and the corrupt police refuse to assist him, Wei sets out on his own to locate her. Navin, a tenacious journalist whose wife has mysteriously vanished, is his only ally. In this explosive martial arts showdown, the unlikely duo fights the kidnappers ruthlessly driven by a furious vengeance.', '/assets/posters/movie_1280738.jpg', '/assets/backdrops/movie_1280738.jpg', '/assets/video/clip_18972999.mp4', 7367, 8, 'zh');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (13, 'Other Mommy', 'movie', '2026', 'Horror', 'TV-14', 0.0, 'A young girl, her family and their home are haunted by a sinister entity that is determined to take up residence inside her. But first, it needs to persuade her to let it in…', '/assets/posters/movie_1400837.jpg', '/assets/backdrops/movie_1400837.jpg', '/assets/video/clip_27152549.mp4', 5787, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (14, 'Heartstopper Forever', 'movie', '2026', 'Romance', 'TV-14', 6.9, 'It''s a new school year for the Truham-Higgs gang. As Nick and Charlie''s relationship deepens, their thoughts turn to life after the last bell rings.', '/assets/posters/movie_1468683.jpg', '/assets/backdrops/movie_1468683.jpg', '/assets/video/clip_27152555.mp4', 6356, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (15, 'Toy Story 5', 'movie', '2026', 'Animation', 'TV-14', 7.4, 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', '/assets/posters/movie_1084244.jpg', '/assets/backdrops/movie_1084244.jpg', '/assets/video/clip_30070091.mp4', 7844, 9, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (16, 'Evil Dead Burn', 'movie', '2026', 'Horror', 'TV-14', 6.7, 'After her husband''s abrupt death, Alice seeks solace with his remaining family — descendants of a leading researcher on demonic possession. As her in-laws transform one by one into creatures that feed on fear, she comes to discover that the vows she took in life survive even in death.', '/assets/posters/movie_1212763.jpg', '/assets/backdrops/movie_1212763.jpg', '/assets/video/clip_30997958.mp4', 7498, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (17, 'The Breadwinner', 'movie', '2026', 'Comedy', 'TV-14', 6.9, 'After his wife Katie lands a once-in-a-lifetime deal on Shark Tank that takes her on a prolonged business trip - lifelong breadwinner Nate Wilcox now has to fend for his family as a first-time stay-at-home dad.', '/assets/posters/movie_1440050.jpg', '/assets/backdrops/movie_1440050.jpg', '/assets/video/clip_35079542.mp4', 6427, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (18, 'Mortal Kombat II', 'movie', '2026', 'Action', 'TV-14', 8.0, 'The fan favorite champions—now joined by Johnny Cage himself—are pitted against one another in the ultimate, no-holds barred, gory battle to defeat the dark rule of Shao Kahn that threatens the very existence of the Earthrealm and its defenders.', '/assets/posters/movie_931285.jpg', '/assets/backdrops/movie_931285.jpg', '/assets/video/clip_18972999.mp4', 7644, 4, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (19, 'Minions & Monsters', 'movie', '2026', 'Adventure', 'TV-14', 6.4, 'This is the rambunctious, ridiculous and totally true story of how the Minions conquered Hollywood, became movie stars, lost everything, unleashed monsters onto the world and then banded together to try and save the planet from the mayhem they had just created.', '/assets/posters/movie_1315772.jpg', '/assets/backdrops/movie_1315772.jpg', '/assets/video/clip_27152549.mp4', 8371, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (20, 'The Devil Wears Prada 2', 'movie', '2026', 'Comedy', 'TV-14', 7.1, 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', '/assets/posters/movie_1314481.jpg', '/assets/backdrops/movie_1314481.jpg', '/assets/video/clip_27152555.mp4', 5721, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (21, 'The East Palace', 'series', '2026', 'Mystery', 'TV-14', 8.0, 'A man who walks the spirit world and a court lady who hears the dead enter the East Palace by the king''s orders — can they unravel its dark secrets?', '/assets/posters/tv_279323.jpg', '/assets/backdrops/tv_279323.jpg', '/assets/video/clip_30070091.mp4', 15941, NULL, 'ko');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (22, 'House of the Dragon', 'series', '2022', 'Sci-Fi & Fantasy', 'TV-14', 8.4, 'The Targaryen dynasty is at the absolute apex of its power, with more than 15 dragons under their yoke. Most empires crumble from such heights. In the case of the Targaryens, their slow fall begins when King Viserys breaks with a century of tradition by naming his daughter Rhaenyra heir to the Iron Throne. But when Viserys later fathers a son, the court is shocked when Rhaenyra retains her status as his heir, and seeds of division sow friction across the realm.', '/assets/posters/tv_94997.jpg', '/assets/backdrops/tv_94997.jpg', '/assets/video/clip_30997958.mp4', 36525, 9, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (23, 'Lucky', 'series', '2026', 'Drama', 'TV-14', 6.8, 'When a multi-million-dollar heist goes sideways, con artist Lucky is forced to go on the run. Pursued by both the FBI and a ruthless crime boss, Lucky must fight for her life—and a way out.', '/assets/posters/tv_278624.jpg', '/assets/backdrops/tv_278624.jpg', '/assets/video/clip_35079542.mp4', 44277, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (24, 'Silo', 'series', '2023', 'Sci-Fi & Fantasy', 'TV-14', 8.2, 'In a ruined and toxic future, thousands live in a giant silo deep underground. After its sheriff breaks a cardinal rule and residents die mysteriously, engineer Juliette starts to uncover shocking secrets and the truth about the silo.', '/assets/posters/tv_125988.jpg', '/assets/backdrops/tv_125988.jpg', '/assets/video/clip_18972999.mp4', 16041, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (25, 'Rick and Morty', 'series', '2013', 'Animation', 'TV-14', 8.7, 'Follows a sociopathic genius scientist who drags his inherently timid grandson on adventures across the universe.', '/assets/posters/tv_60625.jpg', '/assets/backdrops/tv_60625.jpg', '/assets/video/clip_27152549.mp4', 32249, 4, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (26, 'One Piece', 'series', '1999', 'Action & Adventure', 'TV-14', 8.7, 'Years ago, the fearsome Pirate King, Gol D. Roger was executed leaving a huge pile of treasure and the famous "One Piece" behind. Whoever claims the "One Piece" will be named the new King of the Pirates. Monkey D. Luffy, a boy who consumed a "Devil Fruit," decides to follow in the footsteps of his idol, the pirate Shanks, and find the One Piece. It helps, of course, that his body has the properties of rubber and that he''s surrounded by a bevy of skilled fighters and thieves to help him along the way. Luffy will do anything to get the One Piece and become King of the Pirates!', '/assets/posters/tv_37854.jpg', '/assets/backdrops/tv_37854.jpg', '/assets/video/clip_27152555.mp4', 49225, 3, 'ja');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (27, 'Agent Kim Reactivated', 'series', '2026', 'Action & Adventure', 'TV-14', 7.2, 'When an unassuming dad''s daughter goes missing, he dusts off his old black-ops skills to track her down — only to attract the wrong kind of attention.', '/assets/posters/tv_296206.jpg', '/assets/backdrops/tv_296206.jpg', '/assets/video/clip_30070091.mp4', 16637, NULL, 'ko');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (28, 'The Hawk', 'series', '2026', 'Comedy', 'TV-14', 5.0, 'On the back nine of his career, golf legend Lonnie "The Hawk" Hawkins chases one final major — and drags everyone he loves into the chaos.', '/assets/posters/tv_254528.jpg', '/assets/backdrops/tv_254528.jpg', '/assets/video/clip_30997958.mp4', 32405, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (29, 'Spooky in Love', 'series', '2026', 'Comedy', 'TV-14', 9.2, 'When a ghost-seeing heir and an ace prosecutor learn that a single touch makes them a strangely effective duo, they team up to crack unsolved murders.', '/assets/posters/tv_298610.jpg', '/assets/backdrops/tv_298610.jpg', '/assets/video/clip_35079542.mp4', 48036, 1, 'ko');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (30, 'Ride or Die', 'series', '2026', 'Action & Adventure', 'TV-14', 5.0, 'Best friends Debbie and Judith are forced on the run when Debbie discovers Judith isn''t a forensic accountant, she''s an international assassin! With a mysterious figure chasing them, and Debbie''s husband involved in something deeply corrupt, it''s a race against time and a road trip across Europe to untangle the truth and stay alive.', '/assets/posters/tv_241882.jpg', '/assets/backdrops/tv_241882.jpg', '/assets/video/clip_18972999.mp4', 16890, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (31, 'Cape Fear', 'series', '2026', 'Drama', 'TV-14', 7.1, 'When convicted murderer Max Cady is released from prison, he begins infiltrating the family of the married attorneys who helped put him behind bars.', '/assets/posters/tv_277439.jpg', '/assets/backdrops/tv_277439.jpg', '/assets/video/clip_27152549.mp4', 28858, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (32, 'Star Wars: The Mandalorian and Grogu | A Special Look', 'series', '2026', 'Documentary', 'TV-14', 8.3, 'Get ready for "Star Wars: The Mandalorian and Grogu | A Special Look," only in theaters.', '/assets/posters/tv_321564.jpg', '/assets/backdrops/tv_321564.jpg', '/assets/video/clip_27152555.mp4', 48564, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (33, 'Mushoku Tensei: Jobless Reincarnation', 'series', '2021', 'Action & Adventure', 'TV-14', 8.5, 'When a 34-year-old underachiever gets run over by a truck, his story doesn''t end there. Reincarnated in a new world as an infant, Rudy will seize every opportunity to live the life he''s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he''s always dreamed of, he''s embarking on an epic adventure—with all of his past experience intact!', '/assets/posters/tv_94664.jpg', '/assets/backdrops/tv_94664.jpg', '/assets/video/clip_30070091.mp4', 15089, 8, 'ja');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (34, 'FROM', 'series', '2022', 'Mystery', 'TV-14', 8.5, 'Unravel the mystery of a nightmarish town in middle America that traps all those who enter. As the unwilling residents fight to keep a sense of normalcy and search for a way out, they must also survive the threats of the surrounding forest – including the terrifying creatures that come out when the sun goes down.', '/assets/posters/tv_124364.jpg', '/assets/backdrops/tv_124364.jpg', '/assets/video/clip_30997958.mp4', 33812, 7, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (35, 'King of the Hill', 'series', '1997', 'Animation', 'TV-14', 7.4, 'Set in Texas, this animated series follows the life of propane salesman Hank Hill, who lives with his overly confident substitute Spanish teacher wife Peggy, wannabe comedian son Bobby, and naive niece Luanne. Hank has conservative views about God, family, and country, but his values and ethics are often challenged by the situations he, his family, and his beer-drinking neighbors/buddies find themselves in.', '/assets/posters/tv_2122.jpg', '/assets/backdrops/tv_2122.jpg', '/assets/video/clip_35079542.mp4', 52546, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (36, 'Stranger Things', 'series', '2016', 'Action & Adventure', 'TV-14', 8.6, 'When a young boy vanishes, a small town uncovers a mystery involving secret experiments, terrifying supernatural forces, and one strange little girl.', '/assets/posters/tv_66732.jpg', '/assets/backdrops/tv_66732.jpg', '/assets/video/clip_18972999.mp4', 14743, 5, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (37, 'Overdo', 'series', '2026', 'Drama', 'TV-14', 9.0, 'In Republican Shanghai, Murong Qingyi, a warlord’s son swapped at birth, endures years of torment. His life changes when Ren Susu saves him, but tragedy strikes her family because of it. Years later, love sparks between them, but Ren Susu fakes her death to save another, leaving Qingyi heartbroken. Three years on, she returns as his future sister-in-law. Love, hate, betrayal, and old wounds resurface. As war looms, the two must defy fate together, but can love survive a nation’s fall?', '/assets/posters/tv_289139.jpg', '/assets/backdrops/tv_289139.jpg', '/assets/video/clip_27152549.mp4', 31865, 2, 'zh');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (38, 'X-Men ''97', 'series', '2024', 'Animation', 'TV-14', 8.6, 'The X-Men, a band of mutants who use their uncanny gifts to protect a world that hates and fears them, are challenged like never before, forced to face a dangerous and unexpected new future.', '/assets/posters/tv_138502.jpg', '/assets/backdrops/tv_138502.jpg', '/assets/video/clip_27152555.mp4', 51398, 6, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (39, 'The Westies', 'series', '2026', 'Drama', 'TV-14', 6.1, 'As the Javits Center construction project ignites a battle for profit in early 1980s Hell''s Kitchen, a generational rift threatens the uneasy peace between violent Irish gang the Westies and the Mafia, and draws FBI heat.', '/assets/posters/tv_286709.jpg', '/assets/backdrops/tv_286709.jpg', '/assets/video/clip_30070091.mp4', 14750, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (40, 'THE GHOST IN THE SHELL', 'series', '2026', 'Animation', 'TV-14', 8.3, '2029, a near-future Japan. The full cyborg Motoko Kusanagi envisions a task force that preemptively strikes emerging threats. She and her team are scouted by Daisuke Aramaki as Public Security Section 9, AKA the "Shell Squad." An international conspiracy hints at a hacker known as The "Puppet Master." What fate awaits Kusanagi? What is the hacker''s endgame? A new era of cyberpunk action begins!', '/assets/posters/tv_255358.jpg', '/assets/backdrops/tv_255358.jpg', '/assets/video/clip_30997958.mp4', 32072, NULL, 'ja');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (41, 'Supergirl', 'movie', '2026', 'Action', 'TV-14', 6.1, 'When an unexpected and ruthless adversary strikes too close to home, Kara Zor-El, aka Supergirl, reluctantly joins forces with an unlikely companion on an epic, interstellar journey of vengeance and justice.', '/assets/posters/movie_1081003.jpg', '/assets/backdrops/movie_1081003.jpg', '/assets/video/clip_35079542.mp4', 6564, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (42, 'Project Hail Mary', 'movie', '2026', 'Science Fiction', 'TV-14', 8.7, 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '/assets/posters/movie_687163.jpg', '/assets/backdrops/movie_687163.jpg', '/assets/video/clip_18972999.mp4', 8146, 2, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (43, 'Desire', 'movie', '2026', 'Mystery', 'TV-14', 6.8, 'Lucero’s life appears immaculate: a wealthy household, a devoted husband, and two children who embody the promise of a perfect family. Yet beneath this surface simmers a quiet dissatisfaction. When Matías, a young swimming coach hired by her husband, enters their lives, Lucero finds herself pulled into a risky and consuming relationship. As secrecy, desire, and jealousy tighten their grip, the boundaries within the family begin to collapse, placing mother and daughter in a dangerous emotional triangle that threatens to shatter everything Lucero has built.', '/assets/posters/movie_1668364.jpg', '/assets/backdrops/movie_1668364.jpg', '/assets/video/clip_27152549.mp4', 7520, NULL, 'es');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (44, 'Passenger', 'movie', '2026', 'Horror', 'TV-14', 7.3, 'After a young couple witnesses a gruesome highway accident, they soon realize they did not leave the crash scene alone, as a demonic presence called the Passenger that won''t stop until it claims them both turns their van life adventure into a nightmare.', '/assets/posters/movie_1368314.jpg', '/assets/backdrops/movie_1368314.jpg', '/assets/video/clip_27152555.mp4', 7111, 10, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (45, 'Affair at the Nuns'' Temple: Paradise Sex', 'movie', '1998', NULL, 'TV-14', 1.7, 'Japanese nunsplitation movie from 1998', '/assets/posters/movie_261639.jpg', NULL, '/assets/video/clip_30070091.mp4', 5731, NULL, 'ja');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (46, 'Your Heart Will Be Broken', 'movie', '2026', 'Romance', 'TV-14', 7.1, 'High school student Polina is saved from bullying at her new school and makes a deal with the main bully Bars: he must pretend to be her boyfriend and protect her, and she must do everything he says. During this game, the couple develops real feelings, but her family and classmates have reasons to separate the lovers.', '/assets/posters/movie_1523145.jpg', '/assets/backdrops/movie_1523145.jpg', '/assets/video/clip_30997958.mp4', 5948, NULL, 'ru');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (47, 'Deep Water', 'movie', '2026', 'Horror', 'TV-14', 7.5, 'A group of international passengers on a flight from Los Angeles to Shanghai is forced to make an emergency landing in shark-infested waters. The terrified group is forced to work together and overcome their differences if they hope to escape their sinking plane and the frenzy of sharks drawn to the wreckage.', '/assets/posters/movie_1127384.jpg', '/assets/backdrops/movie_1127384.jpg', '/assets/video/clip_35079542.mp4', 8614, 7, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (48, 'Michael', 'movie', '2026', 'Music', 'TV-14', 8.7, 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', '/assets/posters/movie_936075.jpg', '/assets/backdrops/movie_936075.jpg', '/assets/video/clip_18972999.mp4', 8682, 1, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (49, 'Lecture Room', 'series', '2001', 'Talk', 'TV-14', 7.0, '', '/assets/posters/tv_237020.jpg', '/assets/backdrops/tv_237020.jpg', '/assets/video/clip_27152549.mp4', 33014, NULL, 'zh');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (50, 'Binnelanders', 'series', '2005', 'Soap', 'TV-14', 5.5, 'A South African Afrikaans soap opera. It is set in and around the fictional private hospital, Binneland Kliniek, in Pretoria, and the storyline follows the trials, trauma and tribulations of the staff and patients of the hospital.', '/assets/posters/tv_206559.jpg', '/assets/backdrops/tv_206559.jpg', '/assets/video/clip_27152555.mp4', 55279, NULL, 'af');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (51, '7de Laan', 'series', '2000', 'Soap', 'TV-14', 8.3, '7de Laan is an extraordinary microcosm where good and bad, evil and wholesome characters find themselves forming part of a wholesome community where no matter what – everyone counts and everyone cares…', '/assets/posters/tv_17887.jpg', '/assets/backdrops/tv_17887.jpg', '/assets/video/clip_30070091.mp4', 14881, 10, 'af');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (52, 'C.I.D.', 'series', '1998', 'Action & Adventure', 'TV-14', 5.7, 'A team of dedicated men and women in the Crime Investigation Department will risk everything to solve Mumbai''s toughest, most complicated crimes.', '/assets/posters/tv_15226.jpg', '/assets/backdrops/tv_15226.jpg', '/assets/video/clip_30997958.mp4', 35018, NULL, 'hi');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (53, 'Late Show with David Letterman', 'series', '1993', 'Talk', 'TV-14', 6.4, 'David Letterman uses mature humor to appeal to his audience in this weeknight series, which gets its music from a house band led by Paul Shaffer. Among the show''s most-famous segments are the Top Ten List and Stupid Pet Tricks, the latter of which subsequently led to an additional recurring segment called Stupid Human Tricks.', '/assets/posters/tv_498.jpg', '/assets/backdrops/tv_498.jpg', '/assets/video/clip_35079542.mp4', 47352, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (54, 'The Tonight Show Starring Johnny Carson', 'series', '1962', 'Talk', 'TV-14', 7.5, 'The Tonight Show Starring Johnny Carson is a talk show hosted by Johnny Carson under The Tonight Show franchise from 1962 to 1992. It originally aired during late-night. For its first ten years, Carson''s Tonight Show was based in New York City with occasional trips to Burbank, California; in May 1972, the show moved permanently to Burbank, California. In 2002, The Tonight Show Starring Johnny Carson was ranked #12 on TV Guide''s 50 Greatest TV Shows of All Time.', '/assets/posters/tv_2261.jpg', '/assets/backdrops/tv_2261.jpg', '/assets/video/clip_18972999.mp4', 15775, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (55, 'Egoli: Place of Gold', 'series', '1992', 'Soap', 'TV-14', 7.2, 'A South African television soap opera created by Franz Marx which revolves around the daily ups, downs, trials and tribulations of a handful of families in and around Johannesburg (which is often referred to as eGoli - the City of Gold)', '/assets/posters/tv_12415.jpg', '/assets/backdrops/tv_12415.jpg', '/assets/video/clip_27152549.mp4', 31898, NULL, 'af');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (56, 'Jeopardy!', 'series', '1984', 'Reality', 'TV-14', 6.9, 'America''s favorite quiz show where contestants are presented with general knowledge clues in the form of answers, and must phrase their responses in question form.', '/assets/posters/tv_2912.jpg', '/assets/backdrops/tv_2912.jpg', '/assets/video/clip_27152555.mp4', 46247, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (57, 'The Daily Show', 'series', '1996', 'News', 'TV-14', 6.4, 'The World''s Fakest News Team tackle the biggest stories in news, politics and pop culture.', '/assets/posters/tv_2224.jpg', '/assets/backdrops/tv_2224.jpg', '/assets/video/clip_30070091.mp4', 15827, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (58, 'Law & Order: Special Victims Unit', 'series', '1999', 'Crime', 'TV-14', 8.0, 'In the criminal justice system, sexually-based offenses are considered especially heinous. In New York City, the dedicated detectives who investigate these vicious felonies are members of an elite squad known as the Special Victims Unit. These are their stories.', '/assets/posters/tv_2734.jpg', '/assets/backdrops/tv_2734.jpg', '/assets/video/clip_30997958.mp4', 31902, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (59, 'The Late Show with Stephen Colbert', 'series', '2015', 'Comedy', 'TV-14', 6.1, 'Stephen Colbert brings his signature satire and comedy to The Late Show with Stephen Colbert, the #1 show in late night, where he talks with an eclectic mix of guests about what is new and relevant in the worlds of politics, entertainment, business, music, technology, and more. Featuring bandleader Jon Batiste with his band Stay Human, the Emmy Award-nominated show is broadcast from the historic Ed Sullivan Theater.', '/assets/posters/tv_63770.jpg', '/assets/backdrops/tv_63770.jpg', '/assets/video/clip_35079542.mp4', 52364, NULL, 'en');
INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES (60, 'Rote Rosen', 'series', '2006', 'Soap', 'TV-14', 3.0, 'Rote Rosen is a German telenovela produced by Studio Hamburg Serienwerft Lüneburg and broadcast by Das Erste since November 6, 2006. The show is a complex telenovela, who tells one love story every season about women in their forties.', '/assets/posters/tv_27181.jpg', '/assets/backdrops/tv_27181.jpg', '/assets/video/clip_18972999.mp4', 14981, NULL, 'de');
